from collections import defaultdict

def largest_subset(nums):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def is_divisible(x, y):
        return x % y == 0 or y % x == 0

    nums.sort()
    dp = defaultdict(int)
    max_size = 0

    for i in range(len(nums)):
        dp[nums[i]] = 1  # Each number is a subset of size 1
        for j in range(i):
            if is_divisible(nums[i], nums[j]):
                dp[nums[i]] = max(dp[nums[i]], dp[nums[j]] + 1)
        max_size = max(max_size, dp[nums[i]])

    return max_size
